SET NAMES utf8mb4;

-- 与 02_phone.sql 同模式：先加列再灌数据。
-- 若缺失此 ALTER，本文件会在干净克隆时以 ERROR 1054 (Unknown column 'avatar') 中断，
-- 导致 mysql-auth 容器退出、整个 compose 栈起不来。
ALTER TABLE sentinel_user ADD COLUMN avatar MEDIUMTEXT NULL COMMENT '头像 data URL' AFTER nickname;

UPDATE sentinel_user SET avatar = 'data:image/svg+xml;base64,' WHERE username = '张伟' AND (avatar IS NULL OR avatar = '');
UPDATE sentinel_user SET avatar = 'data:image/svg+xml;base64,' WHERE username = '刘洋' AND (avatar IS NULL OR avatar = '');
